// End-to-end isolated fixture. The fake driver emits permission DATA and never
// executes commands. The only proof used is generated by this temporary server.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { afterAll, beforeAll, expect, it } from 'vitest';
import { raiseLevel } from './testing/raise-level.ts';
import { launchVerificationServer, runControlMurage, type VerificationServer } from '../scripts/control-murage.ts';
import { openSse } from './testing/sse.ts';
let fixture: VerificationServer;
let headers: Record<string,string>;
const evidence=new URL('../evidence/bld7-toolid-s4b/',import.meta.url);
mkdirSync(evidence,{recursive:true});
const commands:unknown[]=[];
async function api(method:string,path:string,body?:unknown):Promise<any> {
  const res=await fetch(fixture.info.url+path,{method,headers:{...headers,'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
  commands.push({method,path,body,status:res.status}); expect(res.ok).toBe(true); return res.json();
}
beforeAll(async()=>{
  const anchor='emit({ type: "item.completed", itemType: "assistant_text", origin: "engine", text: "Hello from late", threadId: turn.threadId, turnId });';
  const replacement=`const variant = JSON.stringify(turn.prompt ?? turn.text);
    const marks=r13Marks;
    if(variant.includes('tainted-')) marks.markTurnOutside(turn.threadId,variant.includes('tainted-unknown-')?'outside tool':'web page');
    const fs=r13Fs; const path=r13Path;
    fs.appendFileSync(path.join(process.env.MURAGE_DATA_DIR,'r13-turn-states.jsonl'),JSON.stringify({variant,outside:marks.turnOutsideRead(turn.threadId)})+'\\n');
    const command = variant.includes('routine-parity') ? 'cat ~/.ssh/id_rsa' : variant.includes('cleanup-fixture') ? 'rm -rf build' : variant.includes('wipe-fixture') ? 'rm -rf /' : variant.includes('quote-fixture') ? "printf '" : 'printf ok';
    emit({ type: 'request.opened', requestType: 'permission', tool: 'Bash', summary: command,
      toolCall: { name: 'Bash', input: { command, cwd: turn.cwd } },
      ...((variant.includes('cut-fixture') || variant.includes('wipe-fixture')) ? { toolInputTruncated: true } : {}),
      ...(variant.includes('env-fixture') ? { execEnv: { env: {}, absent: [], cwd: turn.cwd, shell: ['sh'], capture: 'posix-env-0', unchecked: { reason: 'timeout' } } } : {}),
      requestId: turnId + '-approval', threadId: turn.threadId, turnId }); return;`;
  fixture=await launchVerificationServer(process.env,undefined,{instrumentationSource:`
    await import(${JSON.stringify(new URL('./testing/idle-load-preload.mjs',import.meta.url).href)});
    const fs=await import('node:fs'); const path=await import('node:path'); const {registerHooks}=await import('node:module');
    registerHooks({load(url,ctx,next){
      // The simulated engine emits only permission data and is fully observed.
      // Admit this fixture kind into the covered-driver set; production is unchanged.
      if(url.endsWith('/email/external-marks.ts')) {
        const source=fs.readFileSync(new URL(url),'utf8').replace('COVERED_DRIVERS.has(driverKind)', '(driverKind === "fakeLateTerminal" || COVERED_DRIVERS.has(driverKind))');
        return {format:'module-typescript',shortCircuit:true,source};
      }
      if(!url.endsWith('/fake-late-terminal-driver.ts'))return next(url,ctx);
      let source="import * as r13Marks from '../email/external-marks.ts'; import * as r13Fs from 'node:fs'; import * as r13Path from 'node:path';\\n"+fs.readFileSync(new URL(url),'utf8');
      if(!source.includes(${JSON.stringify(anchor)}))throw Error('fixture anchor changed');
      source=source.replaceAll(${JSON.stringify(anchor)},${JSON.stringify(replacement)});
      source=source.replace('respondToRequest: async () => "unavailable" as const,',
        'respondToRequest: async (threadId, requestId, response) => { const entry = active.get(threadId); if (!entry) return "unavailable" as const; emit({ type: "item.completed", itemType: "assistant_text", origin: "engine", text: "fixture " + response.behavior, threadId, turnId: entry.turnId }); active.delete(threadId); emit({ type: "turn.completed", ok: true, threadId, turnId: entry.turnId }); return "applied" as const; },');
      return {format:'module-typescript',shortCircuit:true,source};
    }});
    const {BUILT_IN_DRIVERS}=await import(${JSON.stringify(new URL('./drivers/builtIn.ts',import.meta.url).href)});
    const {makeLateTerminalDriver}=await import(${JSON.stringify(new URL('./testing/fake-late-terminal-driver.ts',import.meta.url).href)});
    BUILT_IN_DRIVERS.push(makeLateTerminalDriver());
    const file=path.join(process.env.MURAGE_DATA_DIR,'config.json');const cfg=JSON.parse(fs.readFileSync(file,'utf8'));
    cfg.instances.r13={driver:'fakeLateTerminal'};fs.writeFileSync(file,JSON.stringify(cfg));
  `}).catch(error=>{
    const path=String(error).match(/see (\/tmp\/[^\s]+\.log)/)?.[1];
    if(path&&existsSync(path))writeFileSync(new URL('fixture-startup-failure.log',evidence),readFileSync(path));
    throw error;
  });
  writeFileSync(new URL('fixture-launch.json',evidence),JSON.stringify(fixture.info,null,2)+'\n');
  const proof=await (await fetch(fixture.info.url+'/api/desktop-secret')).json() as {secret:string};
  headers={'x-murage-surface':'desktop','x-murage-surface-secret':proof.secret};
},60000);
afterAll(async()=>{
  try {if(fixture){if(existsSync(fixture.info.dataDir+'/r13-turn-states.jsonl'))writeFileSync(new URL('fixture-turn-states.jsonl',evidence),readFileSync(fixture.info.dataDir+'/r13-turn-states.jsonl'));writeFileSync(new URL('fixture-server.log',evidence),readFileSync(fixture.info.logPath));writeFileSync(new URL('fixture-commands.json',evidence),JSON.stringify(commands,null,2)+'\n');}}
  finally{await fixture?.close();}
});
it.each(['clean','quote','cut','env','cleanup','wipe','tainted-quote','tainted-cut','tainted-env','tainted-unknown-quote','tainted-unknown-cut','tainted-unknown-env'])('%s owner request goes through the production gate',async variant=>{
  const {bot}=await api('POST','/api/bots',{name:'R13 '+variant,modelSelection:{instanceId:'r13',model:'late-1'}});
  await api('PATCH',`/api/bots/${bot.id}`,{computer:'off',browser:false,composio:false,autoReview:'off'});
  await api('PATCH',`/api/bots/${bot.id}/tasks/${bot.threadId}`,{noLimits:true,acknowledgeNoLimits:true});
  const stream=await openSse(fixture.info.url+'/api/events');
  try {
    await stream.until(frame=>frame.kind==='hello');
    await api('POST',`/api/bots/${bot.id}/messages`,{text:variant+'-fixture',threadId:bot.threadId});
    await stream.until(frame=>frame.kind==='runtime'&&frame.event?.type==='request.opened'&&frame.event?.threadId===bot.threadId);
    const waited=await runControlMurage(['wait','--bot',bot.id,'--timeout','5','--url',fixture.info.url]);
    const transcript=await runControlMurage(['messages','--bot',bot.id,'--limit','20','--url',fixture.info.url]);
    const messages=await api('GET',`/api/threads/${bot.threadId}/messages?limit=20`);
    const decisions=await api('GET','/api/decisions?limit=100');
    writeFileSync(new URL(`fixture-${variant}.json`,evidence),JSON.stringify({waited,transcript,messages,decisions},null,2)+'\n');
    if(variant!=='wipe'&&!variant.startsWith('tainted-')) {
      expect(waited).toMatchObject({status:'settled'});
      expect(messages.messages.some((m:any)=>m.text==='fixture allow')).toBe(true);
      expect(decisions.decisions).toContainEqual(expect.objectContaining({threadId:bot.threadId,decision:'auto-approved',source:'no-limits'}));
    } else {
      expect(waited).toMatchObject({status:'needs-user'});
      expect(messages.messages.some((m:any)=>m.card?.requestId&&m.card.answered===undefined)).toBe(true);
      expect(decisions.decisions).toContainEqual(expect.objectContaining({threadId:bot.threadId,decision:'card-shown',source:'always-ask'}));
      expect(decisions.decisions.some((d:any)=>d.threadId===bot.threadId&&d.decision==='auto-approved')).toBe(false);
    }
  } finally {await api('POST',`/api/bots/${bot.id}/interrupt`,{threadId:bot.threadId});stream.close();}
},25000);

// bld3 replay: both routes showed one sensitive-guard card at 292df98d8,
// but zero at aaa0e298e. Exercise the actual manager/scheduler, never a live app.
it.each(['manual', 'scheduled'])('%s routine preserves the 1.0.18 card', async route => {
  const {bot} = await api('POST','/api/bots',{name:'Routine parity '+route,modelSelection:{instanceId:'r13',model:'late-1'}});
  const raised = await raiseLevel(async (method,path,body) => ({status:200,body:await api(method,path,body)}),bot.id,
    {noLimits:true,acknowledgeNoLimits:true,computer:'off',browser:false,composio:false,autoReview:'off'});
  expect(raised.status).toBe(200);
  const {routine} = await api('POST','/api/routines',{name:'Routine parity '+route,prompt:'routine-parity',botId:bot.id,
    runOn:'ember',permissionMode:'unlimited',enabled:route==='scheduled',
    schedule:{type:'once',at:Date.now()+(route==='scheduled'?1500:3600000)},timeoutMinutes:20});
  let threadId:string|undefined;
  const stream=await openSse(fixture.info.url+'/api/events');
  try {
    await stream.until(frame=>frame.kind==='hello');
    if(route==='manual') await api('POST',`/api/routines/${routine.id}/run`);
    const deadline=Date.now()+90000;
    while(Date.now()<deadline) {
      const {runs}=await api('GET','/api/routines');
      threadId=runs.find((run:any)=>run.routineId===routine.id)?.threadId;
      if(threadId) break;
      await new Promise(resolve=>setTimeout(resolve,200));
    }
    expect(threadId).toBeTruthy();
    await stream.until(frame=>frame.kind==='runtime'&&frame.event?.type==='request.opened'&&frame.event?.threadId===threadId);
    await api('POST',`/api/bots/${bot.id}/tasks/${threadId}?messages=0`,{});
    const waited=await runControlMurage(['wait','--bot',bot.id,'--timeout','5','--url',fixture.info.url]);
    const transcript=await runControlMurage(['messages','--bot',bot.id,'--limit','20','--url',fixture.info.url]);
    const messages=await api('GET',`/api/threads/${threadId}/messages?limit=20`);
    const {decisions}=await api('GET','/api/decisions?limit=200');
    const cards=messages.messages.filter((m:any)=>m.card?.requestId&&m.card.answered===undefined);
    const rows=decisions.filter((d:any)=>d.threadId===threadId);
    writeFileSync(new URL(`routine-${route}.json`,evidence),JSON.stringify({base:'292df98d8',baseCards:1,cards:cards.length,waited,transcript,messages,decisions:rows},null,2)+'\n');
    expect(waited).toMatchObject({status:'needs-user'});
    expect(cards).toHaveLength(1);
    expect(rows.filter((d:any)=>d.decision==='card-shown')).toEqual([expect.objectContaining({source:'sensitive-guard'})]);
    expect(rows.some((d:any)=>d.decision==='auto-approved')).toBe(false);
  } finally {
    if(threadId) await api('POST',`/api/bots/${bot.id}/interrupt`,{threadId});
    await api('PATCH',`/api/routines/${routine.id}`,{enabled:false});
    stream.close();
  }
},120000);
